#!/usr/bin/env python3
"""
Validation script for pipeline outputs.
Runs checks on cleaned stops, city clusters, and other key outputs.
"""

import csv
import json
import os
import sys
from pathlib import Path

def read_csv(path: str) -> list:
    """Read a CSV file and return list of rows."""
    rows = []
    with open(path, 'r', newline='') as f:
        reader = csv.DictReader(f)
        for row in reader:
            rows.append(row)
    return rows

def write_json(path: str, data: dict) -> None:
    """Write data to JSON file."""
    with open(path, 'w') as f:
        json.dump(data, f, indent=2)

def check_stop_files_exist(path: str) -> bool:
    """Check if required stop files exist."""
    expected_files = [
        't05_clean_stops.csv',
        't05_clean_stop_times.csv',
        't08_pois_clean.csv',
        't10_accessibility_scores.csv',
        't13_city_clusters.csv'
    ]
    for file_path in expected_files:
        if not os.path.exists(path + file_path):
            return False
    return True

def check_stop_data_format(path: str) -> bool:
    """Check if stop CSV has valid format."""
    try:
        rows = read_csv(path)
        if not rows:
            return False
        # Check header
        header = rows[0]
        required_cols = ['stop_id', 'stop_name', 'stop_lat', 'stop_lon']
        for col in required_cols:
            if col not in header:
                return False
        return True
    except Exception:
        return False

def check_stop_data_has_columns(path: str) -> bool:
    """Check if stop CSV has required columns."""
    try:
        rows = read_csv(path)
        if not rows:
            return False
        header = rows[0]
        required_cols = ['stop_id', 'stop_name', 'stop_lat', 'stop_lon']
        for col in required_cols:
            if col not in header:
                return False
        return True
    except Exception:
        return False

def check_stop_data_has_data_rows(path: str) -> bool:
    """Check if stop CSV has data rows."""
    try:
        rows = read_csv(path)
        return len(rows) > 1
    except Exception:
        return False

def check_stop_data_no_null_lat_lon(path: str) -> bool:
    """Check for null lat/lon values."""
    try:
        rows = read_csv(path)
        if not rows:
            return False
        for row in rows:
            if row.get('stop_lat') is None or row.get('stop_lon') is None:
                return False
        return True
    except Exception:
        return False

def check_city_cluster_files_exist(path: str) -> bool:
    """Check if required city cluster files exist."""
    expected_files = [
        't13_city_clusters.csv',
        't13_cluster_profiles.csv'
    ]
    for file_path in expected_files:
        if not os.path.exists(path + file_path):
            return False
    return True

def check_city_cluster_data_format(path: str) -> bool:
    """Check if city cluster CSV has valid format."""
    try:
        rows = read_csv(path)
        if not rows:
            return False
        # Check header
        header = rows[0]
        required_cols = ['city_id', 'city_name', 'year', 'cluster_id']
        for col in required_cols:
            if col not in header:
                return False
        return True
    except Exception:
        return False

def check_city_cluster_data_has_columns(path: str) -> bool:
    """Check if city cluster CSV has required columns."""
    try:
        rows = read_csv(path)
        if not rows:
            return False
        header = rows[0]
        required_cols = ['city_id', 'city_name', 'year', 'cluster_id']
        for col in required_cols:
            if col not in header:
                return False
        return True
    except Exception:
        return False

def check_city_cluster_data_has_data_rows(path: str) -> bool:
    """Check if city cluster CSV has data rows."""
    try:
        rows = read_csv(path)
        return len(rows) > 1
    except Exception:
        return False

def check_city_cluster_data_no_null_values(path: str) -> bool:
    """Check for null values in required columns."""
    try:
        rows = read_csv(path)
        if not rows:
            return False
        header = rows[0]
        required_cols = ['city_id', 'city_name', 'year', 'cluster_id']
        for col in required_cols:
            if col in header:
                if header[col] is None:
                    return False
        return True
    except Exception:
        return False

def run_checks() -> list:
    """Run all validation checks and return results."""
    results = []
    base_path = Path('.')

    # Check stop files
    results.append({
        "check_name": "clean_stop_files_exist",
        "passed": check_stop_files_exist(base_path),
        "message": "All required cleaned stop files exist in outputs directory"
    })

    results.append({
        "check_name": "clean_stop_data_format_valid",
        "passed": check_stop_data_format(base_path),
        "message": "Clean stop CSV contains valid CSV format with header row"
    })

    results.append({
        "check_name": "clean_stop_data_has_required_columns",
        "passed": check_stop_data_has_columns(base_path),
        "message": "Clean stop data contains required columns: stop_id, stop_name, stop_lat, stop_lon"
    })

    results.append({
        "check_name": "clean_stop_data_has_data_rows",
        "passed": check_stop_data_has_data_rows(base_path),
        "message": "Clean stop data contains multiple data rows indicating valid data population"
    })

    results.append({
        "check_name": "clean_stop_data_has_no_null_lat_lon",
        "passed": check_stop_data_no_null_lat_lon(base_path),
        "message": "Clean stop data contains no null values in latitude and longitude columns"
    })

    # Check city cluster files
    results.append({
        "check_name": "city_cluster_files_exist",
        "passed": check_city_cluster_files_exist(base_path),
        "message": "All required city cluster files exist in outputs directory"
    })

    results.append({
        "check_name": "city_cluster_data_format_valid",
        "passed": check_city_cluster_data_format(base_path),
        "message": "City cluster CSV contains valid CSV format with header row"
    })

    results.append({
        "check_name": "city_cluster_data_has_required_columns",
        "passed": check_city_cluster_data_has_columns(base_path),
        "message": "City cluster data contains required columns: city_id, city_name, year, cluster_id"
    })

    results.append({
        "check_name": "city_cluster_data_has_data_rows",
        "passed": check_city_cluster_data_has_data_rows(base_path),
        "message": "City cluster data contains multiple data rows indicating valid data population"
    })

    results.append({
        "check_name": "city_cluster_data_has_no_null_values",
        "passed": check_city_cluster_data_no_null_values(base_path),
        "message": "City cluster data contains no null values in required columns"
    })

    return results

def main():
    """Run validation and write summary."""
    results = run_checks()

    summary = {
        "checks": results
    }

    output_path = base_path / 'outputs' / 't14_validation_summary.json'
    write_json(output_path, summary)

    print(f"Validation complete. Summary written to {output_path}")
    return 0

if __name__ == '__main__':
    sys.exit(main())

